mapper.select:
SELECT id, task_code, agent_type, biz_type, biz_id, biz_ref, input_snapshot,
       output_result, alert_level, score, confidence, suggestion, matched_rules,
       cost_ms, model_version, status, error_msg, caller_id, caller_name, source,
       tenant_id, provider_trace_id, created_at, updated_at, deleted
FROM pmis_agent_prediction

    deleted = 0

        AND biz_type = #{bizType}


        AND biz_id = #{bizId}


        AND agent_type = #{agentType}


ORDER BY created_at DESC

SELECT id, task_code, agent_type, biz_type, biz_id, biz_ref, input_snapshot,
       output_result, alert_level, score, confidence, suggestion, matched_rules,
       cost_ms, model_version, status, error_msg, caller_id, caller_name, source,
       tenant_id, provider_trace_id, created_at, updated_at, deleted
FROM pmis_agent_prediction

    deleted = 0 AND status = 'SUCCESS'

        AND agent_type = #{agentType}


        AND alert_level = #{alertLevel}


ORDER BY created_at DESC

    LIMIT #{limit}

SELECT COUNT(1) FROM pmis_agent_prediction

    deleted = 0

        AND alert_level = #{alertLevel}


        AND agent_type = #{agentType}


        AND tenant_id = #{tenantId}

SELECT COUNT(1) AS sample_count, COALESCE(AVG(cost_ms)::numeric(10,2), 0) AS avg_ms, COALESCE(percentile_cont(0.50) WITHIN GROUP (ORDER BY cost_ms)::numeric(10,2), 0) AS p50_ms, COALESCE(percentile_cont(0.90) WITHIN GROUP (ORDER BY cost_ms)::numeric(10,2), 0) AS p90_ms, COALESCE(percentile_cont(0.95) WITHIN GROUP (ORDER BY cost_ms)::numeric(10,2), 0) AS p95_ms, COALESCE(MAX(cost_ms), 0) AS max_ms, COALESCE(MIN(cost_ms), 0) AS min_ms FROM pmis_agent_prediction
deleted = 0 AND status = 'SUCCESS' AND cost_ms IS NOT NULL
AND agent_type = #{agentType}
AND created_at >= #{from}
AND created_at <= #{to}
AND tenant_id = #{tenantId}

SELECT agent_type, COUNT(1) AS sample_count, COALESCE(AVG(cost_ms)::numeric(10,2), 0) AS avg_ms, COALESCE(percentile_cont(0.50) WITHIN GROUP (ORDER BY cost_ms)::numeric(10,2), 0) AS p50_ms, COALESCE(percentile_cont(0.95) WITHIN GROUP (ORDER BY cost_ms)::numeric(10,2), 0) AS p95_ms FROM pmis_agent_prediction
deleted = 0 AND status = 'SUCCESS' AND cost_ms IS NOT NULL AND created_at >= #{from} AND created_at <= #{to} AND tenant_id = #{tenantId}
GROUP BY agent_type ORDER BY p95_ms DESC
